# ====================================================================== global layers
_bg_eff = None
BGW, BGH = 384, 216
_bg_surf = None
_bloom_surf = None
STARS = None


def init_worker():
    global S, _bg_eff, _bg_surf, _bloom_surf, STARS, GRAIN
    S = Sync()
    _bg_eff = skia.RuntimeEffect.MakeForShader(BG_SKSL)
    _bg_surf = skia.Surface.MakeRaster(skia.ImageInfo.Make(BGW, BGH, skia.kRGBA_8888_ColorType,
                                                           skia.kPremul_AlphaType))
    _bloom_surf = skia.Surface.MakeRaster(skia.ImageInfo.Make(480, 270, skia.kRGBA_8888_ColorType,
                                                              skia.kPremul_AlphaType))
    r = np.random.default_rng(7)
    STARS = np.stack([r.uniform(0, W, 420), r.uniform(0, H, 420), r.uniform(0.3, 1.0, 420),
                      r.uniform(0, 6.28, 420), r.uniform(0.2, 1.0, 420)], 1)
    GRAIN = [(r.normal(0, 1, (H // 2, W // 2)) * 3).astype(np.int16) for _ in range(6)]


GRAIN = None
LIN = skia.SamplingOptions(skia.FilterMode.kLinear)


def draw_background(c, t, x):
    lk = look_at(t)
    energy = 0.35 + 0.65 * S.e("pad", t) * 0.6 + 0.5 * kick(t, 0.2) * (section_at(t) in ("drop1", "drop2"))
    u = [BGW, BGH, t, energy, lk["warp"], *lk["c1"], *lk["c2"], *lk["c3"], *lk["bg"], x.split,
         1.0, 0.25, 0.3]
    sh = _bg_eff.makeShader(skia.Data.MakeWithCopy(np.array(u, np.float32).tobytes()))
    bc = _bg_surf.getCanvas()
    bc.drawPaint(skia.Paint(Shader=sh))
    img = _bg_surf.makeImageSnapshot()
    c.drawImageRect(img, skia.Rect(0, 0, BGW, BGH), skia.Rect(-20, -12, W + 20, H + 12), LIN)
    # parallax stars
    sec = section_at(t)
    dens = {"intro": 1.0, "verse": 0.6, "build1": 0.8, "drop1": 1.0, "breakdown": 0.9, "build2": 0.6,
            "drop2": 1.0, "post": 0.7, "outro": 1.0}[sec]
    speed = 40 if sec in ("drop1", "drop2") else 8
    pts_by_alpha = {}
    for sx, sy, depth, ph, br in STARS:
        xx = (sx - t * speed * depth) % W
        yy = (sy + math.sin(t * 0.2 + ph) * 10 * depth) % H
        a = br * dens * (0.55 + 0.45 * math.sin(t * 1.7 + ph * 3))
        key = round(a * 6) / 6
        pts_by_alpha.setdefault((key, depth > 0.75), []).append(skia.Point(xx, yy))
    for (a, big), pts in pts_by_alpha.items():
        if a <= 0:
            continue
        c.drawPoints(skia.Canvas.kPoints_PointMode, pts,
                     paint(WHITE, a * 0.8, stroke=3.2 if big else 1.8, cap_round=True))
    # speed streaks on drop kicks
    if sec in ("drop1", "drop2"):
        k = kick(t, 0.1)
        if k > 0.05:
            for i in range(26):
                yy = rnd("st", i) * H
                xx = (rnd("sx", i) * W - t * 2000 * (0.5 + rnd("sv", i))) % (W + 400) - 200
                c.drawLine(xx, yy, xx + 260 * k, yy, paint(WHITE, 0.25 * k, stroke=2))


def flare(c, x, y, k, col):
    """Anamorphic light streak."""
    if k <= 0.02:
        return
    c.drawRect(skia.Rect.MakeLTRB(x - 900, y - 2, x + 900, y + 2), paint(col, 0.5 * k, blur=6, blend=PLUS))
    c.drawRect(skia.Rect.MakeLTRB(x - 500, y - 1, x + 500, y + 1), paint(WHITE, 0.7 * k, blend=PLUS))
    c.drawCircle(x, y, 60, paint(col, 0.35 * k, blur=40, blend=PLUS))


def kick_index(t):
    a = S.ev["kick"]
    return int(np.searchsorted(a, t, "right") - 1)


def fx_back(c, t):
    """Slow bokeh orbs behind the content, tinted by the section palette."""
    lk = look_at(t)
    cols = [lk["c2"], lk["c3"], lk["c1"]]
    for i in range(16):
        r = 60 + 140 * rnd("bk", i)
        x = (rnd("bx", i) * (W + 2 * r) + t * (12 + 25 * rnd("bv", i))) % (W + 2 * r) - r
        y = rnd("by", i) * H + math.sin(t * 0.3 + i) * 40
        col = tuple(min(1.0, v * 2.2) for v in cols[i % 3])
        a = 0.06 + 0.06 * math.sin(t * 0.7 + i * 1.7) ** 2
        c.drawCircle(x, y, r, paint(col, a, blur=r * 0.35, blend=PLUS))
        c.drawCircle(x, y, r, paint(col, a * 0.8, stroke=1.5, blur=1, blend=PLUS))


def fx_front(c, t):
    sec = section_at(t)
    drop = sec in ("drop1", "drop2")
    # shockwave rings on impacts
    si = S.since("impact", t)
    if si < 1.4:
        u = si / 1.4
        for j in range(2):
            uu = clamp(u - j * 0.08)
            r = 80 + 1300 * ease_out(uu, 2)
            c.drawCircle(CX, CY, r, paint(WHITE, (1 - uu) ** 2 * (0.6 if drop else 0.3), stroke=10 * (1 - uu) + 1,
                                          blur=3, blend=PLUS))
    # smaller rings on claps during drops / builds
    if sec in ("drop1", "drop2", "post"):
        sc = S.since("clap", t)
        if sc < 0.6:
            u = sc / 0.6
            c.drawCircle(CX, CY, 260 + 700 * ease_out(u), paint(CYAN if sec != "drop1" else PINK, (1 - u) ** 2 * 0.35,
                                                                 stroke=4, blur=2, blend=PLUS))
    # spark bursts on drop kicks
    if drop:
        ki = kick_index(t)
        st = S.since("kick", t)
        if 0 <= st < 0.5:
            u = st / 0.5
            for j in range(28):
                ang = rnd("sp", ki, j) * 2 * math.pi
                v = 500 + 900 * rnd("spv", ki, j)
                d0 = 420 + v * ease_out(u) * 0.9
                d1 = d0 + 40 + 120 * (1 - u)
                col = [PINK, CYAN, GOLD][j % 3]
                c.drawLine(CX + math.cos(ang) * d0, CY + math.sin(ang) * d0 * 0.6,
                           CX + math.cos(ang) * d1, CY + math.sin(ang) * d1 * 0.6,
                           paint(col, (1 - u) * 0.7, stroke=3, cap_round=True, blend=PLUS))
    # audio-reactive bars along the bottom edge
    m = S.e("master", t)
    lo, hi, pd = S.e("low", t), S.e("hat", t), S.e("pad", t)
    n = 72
    bw = W / n
    fade = 1 - smooth((t - (DUR - 6)) / 3)
    for i in range(n):
        f = i / (n - 1)
        band = lo * (1 - f) ** 2 + pd * 4 * f * (1 - f) + hi * f ** 2
        h = 6 + 70 * band * (0.6 + 0.4 * math.sin(t * 7 + i * 0.9) ** 2) * (0.5 + 0.5 * m)
        col = mixc(CYAN, PINK, f)
        c.drawRect(skia.Rect.MakeXYWH(i * bw + 3, H - h, bw - 6, h), paint(col, 0.22 * fade, blend=PLUS))


GLITCH_AT = [B(8), B(16), B(32), B(40), B(56), B(64), B(30), B(30, 1), B(30, 2), B(30, 3), B(31)]


def glitch_post(out, t, fi):
    """Horizontal slice displacement for a few frames around section changes."""
    d = min(abs(t - g) for g in GLITCH_AT)
    if d > 0.12:
        return out
    amt = 1 - d / 0.12
    for b in range(9):
        if rnd("gl", fi, b) < 0.45:
            continue
        y0 = int(rnd("gy", fi, b) * H)
        y1 = min(H, y0 + int(10 + 90 * rnd("gh", fi, b)))
        off = int((rnd("go", fi, b) - 0.5) * 160 * amt)
        out[y0:y1] = np.roll(out[y0:y1], off, axis=1)
        out[y0:y1, :, 0] = np.roll(out[y0:y1, :, 0], int(12 * amt), axis=1)
    return out


def apply_transition(kind, u, entering):
    """u: 0 → fully hidden, 1 → fully visible. Returns (alpha, scale, blur, dx)."""
    if kind == "cut":
        return 1.0, 1.0, 0.0, 0.0
    e = smooth(u)
    if kind == "fade":
        return e, 1.0, 0.0, 0.0
    if kind == "zoom":
        s = lerp(1.12, 1.0, ease_out(u)) if entering else lerp(0.9, 1.0, ease_out(u))
        return e, s, (1 - e) * 14, 0.0
    if kind == "whip":
        dx = (1 - ease_out(u, 4)) * (W * 0.6) * (1 if entering else -1)
        return e, 1.0, (1 - e) * 22, dx
    return e, 1.0, 0.0, 0.0


def render_frame(fi):
    t = fi / FPS
    surf = skia.Surface.MakeRaster(skia.ImageInfo.Make(W, H, skia.kRGBA_8888_ColorType,
                                                       skia.kPremul_AlphaType))
    c = surf.getCanvas()
    c.clear(skia.ColorBLACK)
    x = Ctx(t)
    x.zoom = 1.0
    # evaluate shots first so they can set split etc. → draw bg using the previous state is fine;
    # we draw content into a picture first
    rec = skia.PictureRecorder()
    pc = rec.beginRecording(skia.Rect(0, 0, W, H))
    for s in SHOTS:
        if not (s["t0"] <= t < s["t1"] + s["tout"]):
            continue
        lt = t - s["t0"]
        a, sc, bl, dx = 1.0, 1.0, 0.0, 0.0
        if lt < s["tin"]:
            a, sc, bl, dx = apply_transition(s["kin"], lt / s["tin"], True)
        if t >= s["t1"]:
            a2, sc2, bl2, dx2 = apply_transition(s["kout"], 1 - (t - s["t1"]) / s["tout"], False)
            a, sc, bl, dx = a * a2, sc * sc2, bl + bl2, dx + dx2
        if a <= 0.002:
            continue
        pc.save()
        pc.translate(CX + dx, CY)
        pc.scale(sc, sc)
        pc.translate(-CX, -CY)
        if a < 0.999 or bl > 0.3:
            p = skia.Paint(Alphaf=a)
            if bl > 0.3:
                p.setImageFilter(skia.ImageFilters.Blur(bl if s["kin"] != "whip" else bl * 2, bl * 0.4 if
                                                        s["kin"] == "whip" else bl))
            pc.saveLayer(None, p)
            s["fn"](pc, x, t, lt)
            pc.restore()
        else:
            s["fn"](pc, x, t, lt)
        pc.restore()
    pic = rec.finishRecordingAsPicture()

    draw_background(c, t, x)
    fx_back(c, t)
    # camera: kick bump + shake
    c.save()
    zoom = x.zoom * (1 + 0.012 * kick(t, 0.15))
    sh = x.shake
    c.translate(CX + (rnd("shx", fi) - 0.5) * sh * 2, CY + (rnd("shy", fi) - 0.5) * sh * 2)
    c.scale(zoom, zoom)
    c.translate(-CX, -CY)
    # soft dark halo under all content keeps text readable on bright backgrounds
    shadow = skia.Paint(ImageFilter=skia.ImageFilters.DropShadow(0, 3, 9, 9, skia.Color4f(0, 0, 0, 0.8).toColor()))
    c.drawPicture(pic, None, shadow)
    c.restore()
    fx_front(c, t)

    # impacts flash
    fl = S.pulse("impact", t, 0.22) * (0.4 if section_at(t) in ("drop1", "drop2") else 0.12)
    if fl > 0.01:
        c.drawPaint(paint(WHITE, fl, blend=PLUS))
    # intro fade from black
    if t < 2.0:
        c.drawPaint(paint((0, 0, 0), 1 - smooth(t / 2.0)))
    # bloom
    img = surf.makeImageSnapshot()
    bcv = _bloom_surf.getCanvas()
    bcv.clear(skia.ColorBLACK)
    thr = skia.Paint(ColorFilter=skia.ColorFilters.Matrix([
        2.2, 0, 0, 0, -1.25, 0, 2.2, 0, 0, -1.25, 0, 0, 2.2, 0, -1.25, 0, 0, 0, 1, 0]))
    bcv.drawImageRect(img, skia.Rect(0, 0, W, H), skia.Rect(0, 0, 480, 270), LIN, thr)
    bimg = _bloom_surf.makeImageSnapshot()
    bp = skia.Paint(ImageFilter=skia.ImageFilters.Blur(7, 7), BlendMode=PLUS,
                    Alphaf=0.35 + 0.3 * kick(t, 0.2))
    c.drawImageRect(bimg, skia.Rect(0, 0, 480, 270), skia.Rect(0, 0, W, H), LIN, bp)

    arr = surf.makeImageSnapshot().toarray(colorType=skia.kRGBA_8888_ColorType)[..., :3]
    # chromatic aberration
    ch = min(8, int(round(x.chroma * 3)))
    out = arr.astype(np.int16)
    if ch > 0:
        out[:, ch:, 0] = arr[:, :-ch, 0]
        out[:, :-ch, 2] = arr[:, ch:, 2]
    g = GRAIN[fi % len(GRAIN)]
    g = np.repeat(np.repeat(g, 2, 0), 2, 1)
    out += g[..., None]
    np.clip(out, 0, 255, out=out)
    out = glitch_post(out, t, fi)
    return out.astype(np.uint8).tobytes()


# ====================================================================== main
def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--still", nargs="*", type=float)
    ap.add_argument("--range", nargs=2, type=float)
    ap.add_argument("--fps", type=int, default=FPS)
    ap.add_argument("--workers", type=int, default=os.cpu_count())
    ap.add_argument("--out", default=os.path.join(OUT, "好感差距_TheLikingGap.mp4"))
    ap.add_argument("--bitrate", default="14M")
    args = ap.parse_args()

    if args.still:
        init_worker()
        d = os.path.join(OUT, "stills")
        os.makedirs(d, exist_ok=True)
        from PIL import Image
        for ts in args.still:
            t0 = time.time()
            buf = render_frame(int(round(ts * FPS)))
            Image.frombytes("RGB", (W, H), buf).save(os.path.join(d, f"t{ts:07.2f}.png"))
            print(f"{ts:.2f}s rendered in {time.time() - t0:.2f}s")
        return

    import multiprocessing as mp
    t_start, t_end = (args.range if args.range else (0, DUR))
    step = FPS // args.fps
    frames = list(range(int(t_start * FPS), int(t_end * FPS), step))
    out = args.out if not args.range else os.path.join(OUT, f"preview_{t_start:g}_{t_end:g}.mp4")
    cmd = ["ffmpeg", "-y", "-loglevel", "error", "-f", "rawvideo", "-pix_fmt", "rgb24", "-s", f"{W}x{H}",
           "-r", str(args.fps), "-i", "-", "-ss", str(t_start), "-t", str(t_end - t_start),
           "-i", os.path.join(OUT, "music.wav"),
           "-c:v", "libx264", "-preset", "medium" if not args.range else "veryfast",
           "-b:v", args.bitrate, "-maxrate", "20M", "-bufsize", "28M",
           "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "256k", "-movflags", "+faststart", "-shortest", out]
    ff = subprocess.Popen(cmd, stdin=subprocess.PIPE)
    t0 = time.time()
    with mp.Pool(args.workers, initializer=init_worker) as pool:
        for i, buf in enumerate(pool.imap(render_frame, frames, chunksize=4)):
            ff.stdin.write(buf)
            if i % 300 == 0:
                el = time.time() - t0
                print(f"frame {i}/{len(frames)}  {el:.0f}s elapsed, eta {el / max(i, 1) * (len(frames) - i):.0f}s",
                      flush=True)
    ff.stdin.close()
    ff.wait()
    print(f"wrote {out} in {time.time() - t0:.0f}s")


if __name__ == "__main__":
    main()
